import{_ as n,a0 as r,w as p,s as o,ao as d,I as l,x as s,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"開發者需要了解的領域特定語言（DSL） | LCTT x X-CMD","titleTemplate":false,"description":"開發者需要了解的領域特定語言（DSL） | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開發者需要了解的領域特定語言（DSL） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開發者需要了解的領域特定語言（DSL） | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200224 What developers need to know about domain-specific languages","title":"開發者需要了解的領域特定語言（DSL）","tag":"202003","desc":""},"relativePath":"202003/20200224 What developers need to know about domain-specific languages.md","filePath":"[post].md"}'),u={name:"202003/20200224 What developers need to know about domain-specific languages.md"};function L(S,a,D,b,h,g){const i=r("Link");return p(),o("div",null,[a[23]||(a[23]=d(`<h1 id="開發者需要了解的領域特定語言-dsl" tabindex="-1">開發者需要了解的領域特定語言（DSL） <a class="header-anchor" href="#開發者需要了解的領域特定語言-dsl" aria-label="Permalink to “開發者需要了解的領域特定語言（DSL）”">​</a></h1><blockquote><p>領域特定語言是在特定領域下用於特定上下文的語言。作為開發者，很有必要了解領域特定語言的含義，以及為什麼要使用特定領域語言。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/04/112240b0os2988kolritlo.jpg" alt=""></p><p><ruby>領域特定語言<rt>domain-specific language</rt></ruby>（DSL）是一種旨在特定領域下的上下文的語言。這裏的領域是指某種商業上的（例如銀行業、保險業等）上下文，也可以指某種應用程序的（例如 Web 應用、資料庫等）上下文。與之相比的另一個概念是<ruby>通用語言<rt>general-purpose language</rt></ruby>（GPL，LCTT 譯註：注意不要和 GPL 許可證混淆），通用語言則可以廣泛應用於各種商業或應用問題當中。</p><p>DSL 並不具備很強的普適性，它是僅為某個適用的領域而設計的，但它也足以用於表示這個領域中的問題以及構建對應的解決方案。HTML 是 DSL 的一個典型，它是在 Web 應用上使用的語言，儘管 HTML 無法進行數字運算，但也不影響它在這方面的廣泛應用。</p><p>而 GPL 則沒有特定針對的領域，這種語言的設計者不可能知道這種語言會在什麼領域被使用，更不清楚用户打算解決的問題是什麼，因此 GPL 會被設計成可用於解決任何一種問題、適合任何一種業務、滿足任何一種需求。例如 Java 就屬於 GPL，它可以在 PC 或移動設備上運行，嵌入到銀行、金融、保險、製造業等各種行業的應用中去。</p><h3 id="dsl-的類別" tabindex="-1">DSL 的類別 <a class="header-anchor" href="#dsl-的類別" aria-label="Permalink to “DSL 的類別”">​</a></h3><p>從使用方式的角度，語言可以劃分出以下兩類：</p><ul><li>DSL：使用 DSL 形式編寫或表示的語言</li><li><ruby>宿主語言<rt>host language</rt></ruby>：用於執行或處理 DSL 的語言</li></ul><p>由不同的語言編寫並由另一種宿主語言處理的 DSL 被稱為<ruby>外部<rt>external</rt></ruby> DSL。</p><p>以下就是可以在宿主語言中處理的 SQL 形式的 DSL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT account</span></span>
<span class="line"><span>FROM accounts</span></span>
<span class="line"><span>WHERE account = &#39;123&#39; AND branch = &#39;abc&#39; AND amount &gt;= 1000</span></span></code></pre></div><p>因此，只要在規定了詞彙和語法的情況下，DSL 也可以直接使用英語來編寫，並使用諸如 ANTLR 這樣的<ruby>解析器生成器<rt>parser generator</rt></ruby>以另一種宿主語言來處理 DSL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if smokes then increase premium by 10%</span></span></code></pre></div><p>如果 DSL 和宿主語言是同一種語言，這種 DSL 稱為<ruby>內部<rt>internal</rt></ruby>DSL，其中 DSL 由以同一種語義的宿主語言編寫和處理，因此又稱為<ruby>嵌入式<rt>embedded</rt></ruby> DSL。以下是兩個例子：</p><ul><li><p>Bash 形式的 DSL 可以由 Bash 解釋器執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span></code></pre></div></li></ul><p>if today_is_christmas; then apply_christmas_discount; fi</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    同時這也是一段看起來符合英語語法的 Bash。</span></span>
<span class="line"><span>* 使用類似 Java 語法編寫的 DSL： </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    \`\`\`</span></span>
<span class="line"><span>orderValue = orderValue</span></span>
<span class="line"><span>                .applyFestivalDiscount()</span></span>
<span class="line"><span>                .applyCustomerLoyalityDiscount()</span></span>
<span class="line"><span>                .applyCustomerAgeDiscount();</span></span></code></pre></div><pre><code>這一段的可讀性也相當強。
</code></pre><p>實際上，DSL 和 GPL 之間並沒有非常明確的界限。</p><h3 id="dsl-家族" tabindex="-1">DSL 家族 <a class="header-anchor" href="#dsl-家族" aria-label="Permalink to “DSL 家族”">​</a></h3><p>以下這些語言都可以作為 DSL 使用：</p><ul><li>Web 應用：HTML</li><li>Shell：用於類 Unix 系統的 sh、Bash、CSH 等；用於 Windows 系統的 MS-DOS、Windows Terminal、PowerShell 等</li><li>標記語言：XML</li><li>建模：UML</li><li>數據處理：SQL 及其變體</li><li>業務規則管理：Drools</li><li>硬件：Verilog、VHD</li><li>構建工具：Maven、Gradle</li><li>數值計算和模擬：MATLAB（商業）、GNU Octave、Scilab</li><li>解析器和生成器：Lex、YACC、GNU Bison、ANTLR</li></ul><h3 id="為什麼要使用-dsl" tabindex="-1">為什麼要使用 DSL？ <a class="header-anchor" href="#為什麼要使用-dsl" aria-label="Permalink to “為什麼要使用 DSL？”">​</a></h3><p>DSL 的目的是在某個領域中記錄一些需求和行為，在某些方面（例如金融商品交易）中，DSL 的適用場景可能更加狹窄。業務團隊和技術團隊能通過 DSL 有效地協同工作，因此 DSL 除了在業務用途上有所發揮，還可以讓設計人員和開發人員用於設計和開發應用程序。</p><p>DSL 還可以用於生成一些用於解決特定問題的代碼，但生成代碼並不是 DSL 的重點並不在此，而是對專業領域知識的結合。當然，代碼生成在領域工程中是一個巨大的優勢。</p><h3 id="dsl-的優點和缺點" tabindex="-1">DSL 的優點和缺點 <a class="header-anchor" href="#dsl-的優點和缺點" aria-label="Permalink to “DSL 的優點和缺點”">​</a></h3><p>DSL 的優點是，它對於領域的特徵捕捉得非常好，同時它不像 GPL 那樣包羅萬有，學習和使用起來相對比較簡單。因此，它在專業人員之間、專業人員和開發人員之間都提供了一個溝通的橋樑。</p><p>而 DSL 最顯著的缺點就在於它只能用於一個特定的領域和目標。儘管學習起來不算太難，但學習成本仍然存在。如果使用到 DSL 相關的工具，即使對工作效率有所提升，但開發或配置這些工具也會增加一定的工作負擔。另外，如果要設計一款 DSL，設計者必須具備專業領域知識和語言開發知識，而同時具備這兩種知識的人卻少之又少。</p><h3 id="dsl-相關軟件" tabindex="-1">DSL 相關軟件 <a class="header-anchor" href="#dsl-相關軟件" aria-label="Permalink to “DSL  相關軟件”">​</a></h3><p>開源的 DSL 軟件包括：</p><ul><li>Xtext：Xtext 可以與 Eclipse 集成，並支持 DSL 開發。它能夠實現代碼生成，因此一些開源和商業產品都用它來提供特定的功能。用於農業活動建模分析的<ruby>多用途農業數據系統<rt>Multipurpose Agricultural Data System</rt></ruby>（MADS）就是基於 Xtext 實現的一個項目，可惜的是這個項目現在已經不太活躍了。</li><li>JetBrains MPS：JetBrains MPS 是一個可供開發 DSL 的<ruby>集成開發環境<rt>Integrated Development Environment</rt></ruby>，它將文檔在底層存儲為一個抽象樹結構（Microsoft Word 也使用了這一概念），因此它也自稱為一個<ruby>投影編輯器<rt>projectional editor</rt></ruby>。JetBrains MPS 支持 Java、C、JavaScript 和 XML 的代碼生成。</li></ul><h3 id="dsl-的最佳實踐" tabindex="-1">DSL 的最佳實踐 <a class="header-anchor" href="#dsl-的最佳實踐" aria-label="Permalink to “DSL 的最佳實踐”">​</a></h3><p>如果你想使用 DSL，記住以下幾點：</p>`,34)),l("ul",null,[a[3]||(a[3]=l("li",null,"DSL 不同於 GPL，DSL 只能用於解決特定領域中有限範圍內的問題。",-1)),l("li",null,[a[1]||(a[1]=s("不必動輒建立自己的 DSL，可以首先嚐試尋找已有的 DSL。例如 ",-1)),e(i,{href:"http://www.dslfin.org/resources.html"},{default:t(()=>[...a[0]||(a[0]=[s("DSLFIN",-1)])]),_:1}),a[2]||(a[2]=s(" 這個網站就提供了很多金融方面的 DSL。在實在找不到合適的 DSL 的情況下，才需要建立自己的 DSL。",-1))]),a[4]||(a[4]=l("li",null,"DSL 最好像平常的語言一樣具有可讀性。",-1)),a[5]||(a[5]=l("li",null,"儘管代碼生成不是一項必需的工作，但它確實會大大提高工作效率。",-1)),a[6]||(a[6]=l("li",null,"雖然 DSL 被稱為語言，但 DSL 不需要像 GPL 一樣可以被執行，可執行性並不是 DSL 需要達到的目的。",-1)),a[7]||(a[7]=l("li",null,"DSL 可以使用文本編輯器編寫，但專門的 DSL 編輯器可以更輕鬆地完成 DSL 的語法和語義檢查。",-1))]),a[24]||(a[24]=l("p",null,"如果你正在使用或將要使用 DSL，歡迎在評論區留言。",-1)),a[25]||(a[25]=l("hr",null,null,-1)),l("p",null,[a[9]||(a[9]=s("via: ",-1)),e(i,{href:"https://opensource.com/article/20/2/domain-specific-languages"},{default:t(()=>[...a[8]||(a[8]=[s("https://opensource.com/article/20/2/domain-specific-languages",-1)])]),_:1})]),l("p",null,[a[14]||(a[14]=s("作者：",-1)),e(i,{href:"https://opensource.com/users/gammay"},{default:t(()=>[...a[10]||(a[10]=[s("Girish Managoli",-1)])]),_:1}),a[15]||(a[15]=s(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[11]||(a[11]=[s("lujun9972",-1)])]),_:1}),a[16]||(a[16]=s(" 譯者：",-1)),e(i,{href:"https://github.com/HankChow"},{default:t(()=>[...a[12]||(a[12]=[s("HankChow",-1)])]),_:1}),a[17]||(a[17]=s(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...a[13]||(a[13]=[s("wxy",-1)])]),_:1})]),l("p",null,[a[20]||(a[20]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[18]||(a[18]=[s("LCTT",-1)])]),_:1}),a[21]||(a[21]=s(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...a[19]||(a[19]=[s("Linux中國",-1)])]),_:1}),a[22]||(a[22]=s(" 榮譽推出",-1))])])}const y=n(u,[["render",L]]);export{f as __pageData,y as default};
